-- Bani matches a supplier payment by who was paid, not by an exact invoice total.
-- The payment reduces what is owed to that supplier in full and is applied to the oldest
-- approved, undisputed invoices first; anything above what is owed stays unallocated
-- (supplier credit), the same rule as Payables (src/utils/supplierPaymentAllocation.ts).
-- Idempotent: does nothing when already applied; stops if the function changed.
DO $mig$
DECLARE def text := pg_get_functiondef('public.bani_accounting_commit(uuid,uuid,text,text,text,uuid)'::regprocedure);
BEGIN
  IF position('/* bani: oldest first */' in def) > 0 THEN RETURN; END IF;
  IF (length(def) - length(replace(def, $a$IF cnt=0 OR due IS DISTINCT FROM b.money_out OR EXISTS(SELECT 1 FROM payments WHERE bank_transaction_id=b.id) THEN RAISE EXCEPTION 'Supplier match changed';END IF;$a$, ''))) / length($a$IF cnt=0 OR due IS DISTINCT FROM b.money_out OR EXISTS(SELECT 1 FROM payments WHERE bank_transaction_id=b.id) THEN RAISE EXCEPTION 'Supplier match changed';END IF;$a$) <> 1 THEN RAISE EXCEPTION 'bani_accounting_commit: payment check not found exactly once'; END IF;
  IF (length(def) - length(replace(def, $a$INSERT INTO payment_allocations(tenant_id,payment_id,invoice_id,amount_allocated) SELECT r.tenant_id,pay,id,greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0) FROM invoices WHERE tenant_id=r.tenant_id AND supplier_id=p_target_id AND review_status='Approved' AND coalesce(has_disputes,false)=false AND invoice_date<=b.txn_date AND greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0)>0;$a$, ''))) / length($a$INSERT INTO payment_allocations(tenant_id,payment_id,invoice_id,amount_allocated) SELECT r.tenant_id,pay,id,greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0) FROM invoices WHERE tenant_id=r.tenant_id AND supplier_id=p_target_id AND review_status='Approved' AND coalesce(has_disputes,false)=false AND invoice_date<=b.txn_date AND greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0)>0;$a$) <> 1 THEN RAISE EXCEPTION 'bani_accounting_commit: allocation not found exactly once'; END IF;
  def := replace(def, $a$IF cnt=0 OR due IS DISTINCT FROM b.money_out OR EXISTS(SELECT 1 FROM payments WHERE bank_transaction_id=b.id) THEN RAISE EXCEPTION 'Supplier match changed';END IF;$a$, $a$IF cnt=0 OR coalesce(due,0)<=0 OR b.money_out<=0 OR EXISTS(SELECT 1 FROM payments WHERE bank_transaction_id=b.id) THEN RAISE EXCEPTION 'Supplier match changed';END IF;$a$);
  def := replace(def, $a$INSERT INTO payment_allocations(tenant_id,payment_id,invoice_id,amount_allocated) SELECT r.tenant_id,pay,id,greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0) FROM invoices WHERE tenant_id=r.tenant_id AND supplier_id=p_target_id AND review_status='Approved' AND coalesce(has_disputes,false)=false AND invoice_date<=b.txn_date AND greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0)>0;$a$, $a$INSERT INTO payment_allocations(tenant_id,payment_id,invoice_id,amount_allocated) SELECT r.tenant_id,pay,o.id,least(o.open_amount,b.money_out-o.before) FROM (SELECT id,greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0) open_amount,coalesce(sum(greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0)) OVER (ORDER BY invoice_date,created_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) before FROM invoices WHERE tenant_id=r.tenant_id AND supplier_id=p_target_id AND review_status='Approved' AND coalesce(has_disputes,false)=false AND invoice_date<=b.txn_date AND greatest(total_amount-coalesce(amount_paid,0)-coalesce(held_amount,0),0)>0) o WHERE o.before<b.money_out; /* bani: oldest first */$a$);
  EXECUTE def;
END $mig$;
